import json
from pathlib import Path
base=Path('benchmarks/data/hybrid/ab')
rows=json.loads((base/'summary.json').read_text())
get=lambda impl,w,b:next(r for r in rows if r['fixture'].endswith('music3.mp3') and r['format']=='f32le' and r['sessions']==512 and r['implementation']==impl and r['workers']==w and r['budget']==b)
data={'dispatch':[{'label':label,'value':get(impl,w,b)['cpuMsPerAudioSecond'],'color':color} for label,impl,w,b,color in [('Original','original',0,1,1),('Dedicated','dedicated',0,1,2),('4 workers · 1 action','scheduled',4,1,3),('4 workers · 8 actions','scheduled',4,8,4),('4 workers · 32 actions','scheduled',4,32,5)]], 'gaps':[]}
for file,w in [('paced-final-summary.json',1),('paced-final-summary.json',4),('paced-host-summary.json',10)]:
 rs=json.loads((base/file).read_text());selected=next(r for r in rs if r['fixture'].endswith('music3.opus') and r['sessions']==512 and r['implementation']=='scheduled' and r['workers']==w and r['budget']==8)
 reference=next(r for r in rs if r['fixture']==selected['fixture'] and r['format']==selected['format'] and r['sessions']==512 and r['implementation']=='dedicated')
 data['gaps'].append({'label':f'{w} worker'+('s' if w != 1 else '')+' · 8 actions','value':selected['worstInterChunkGapExcessMs'],'reference':reference['worstInterChunkGapExcessMs'],'color':w%5+1})
html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hybrid scheduler measurements</title><style>
:root{font-family:var(--font-sans,system-ui);color:var(--foreground,CanvasText);color-scheme:light dark}body{margin:0}main{display:grid;gap:16px}section{background:var(--card,Canvas);border:1px solid var(--border,GrayText);border-radius:var(--radius,10px);padding:16px;box-sizing:border-box}h2{font-size:17px;font-weight:600;margin:0 0 8px}p{font-size:13px;line-height:1.5;margin:8px 0;color:var(--muted-foreground,GrayText)}.chart{height:205px;display:grid;align-content:center;gap:14px}.row{display:grid;grid-template-columns:145px minmax(80px,1fr) 78px;align-items:center;gap:10px;font-size:13px}.track{height:22px;position:relative;border-bottom:1px solid var(--border,GrayText)}.fill{height:18px;min-width:2px;border-radius:3px}.value{font-family:var(--font-mono,monospace);text-align:right}.marker{position:absolute;top:-4px;bottom:-1px;width:0;border-left:2px dashed var(--foreground,CanvasText)}.axis{display:flex;justify-content:space-between;margin-left:155px;margin-right:88px;font-size:11px;color:var(--muted-foreground,GrayText)}strong{color:var(--foreground,CanvasText)}.stack{display:flex;height:28px;overflow:hidden;border-radius:3px;margin:10px 0}.stack span{height:100%}.legend{display:flex;gap:12px;flex-wrap:wrap;font-size:12px;margin-top:10px}.legend i{display:inline-block;width:9px;height:9px;margin-right:4px}.startupRow{display:flex;justify-content:space-between;font-size:13px}.tag{font-size:12px;color:var(--warning-foreground,CanvasText)}@media(max-width:480px){.row{grid-template-columns:105px minmax(60px,1fr) 65px;font-size:12px;gap:6px}.axis{margin-left:111px;margin-right:71px}h2{font-size:15px}section{padding:12px}}
</style></head><body><main>
<section><h2>Dispatch budget · 512 MP3 → PCM streams</h2><p>CPU milliseconds per delivered audio second. Three interleaved release repetitions; every sample and payload matched.</p><div id="dispatch" class="chart" aria-label="CPU comparison"></div><div class="axis"><span>0</span><span>1.0</span><span>2.0 ms</span></div><p><strong>Eight actions reduced dispatch overhead.</strong> The eight-action budget removed this case’s CPU regression; 32 produced a similar result.</p></section>
<section><h2>Burst headroom · 512 paced Opus streams</h2><p>Worst excess inter-chunk gap, in milliseconds. Budget eight; markers show each sweep’s matched dedicated median.</p><div id="gaps" class="chart" style="height:145px" aria-label="Worst packet-gap comparison"></div><div class="axis"><span>0</span><span>250</span><span>500 ms</span></div><p>Ten workers use the same ten-CPU host as dedicated playback. These synchronized edge-trimming bursts show why low average CPU does not guarantee continuity.</p></section>
<section><h2>Concurrent stalled startup · separate diagnostic</h2><p class="tag"><strong>Dedicated fallback workload — excluded from scheduler performance evidence.</strong></p><div class="startupRow"><span>Original: 1,025 total OS threads</span><span>512 sessions</span></div><div class="stack" id="originalStack"></div><div class="startupRow"><span>Experimental context: 1,029 total OS threads</span><span>512 sessions</span></div><div class="stack" id="poolStack"></div><div class="legend" id="legend"></div><p>The CPU pool does not bound opening/probing. Caller driver threads are measurement scaffolding and are counted separately from engine startup threads.</p></section>
</main><script>
const data=__DATA__;
const color=n=>`var(--chart-${n},Highlight)`;
function rows(id,values,max,unit){const root=document.getElementById(id);for(const item of values){const row=document.createElement('div');row.className='row';const label=document.createElement('span');label.textContent=item.label;const track=document.createElement('div');track.className='track';const fill=document.createElement('div');fill.className='fill';fill.style.width=`${item.value/max*100}%`;fill.style.background=color(item.color);track.append(fill);if(item.reference!==undefined){const marker=document.createElement('div');marker.className='marker';marker.style.left=`${item.reference/max*100}%`;marker.title=`Matched dedicated: ${item.reference.toFixed(1)} ms`;track.append(marker)}const value=document.createElement('span');value.className='value';value.textContent=item.value.toFixed(unit==='ms'?1:3)+(unit?' '+unit:'');row.append(label,track,value);root.append(row)}}
rows('dispatch',data.dispatch,2,'');rows('gaps',data.gaps,500,'ms');
const parts=[['Engine startup',512,1],['Caller drivers',512,2],['CPU workers',4,4],['Main',1,5]];
for(const [id,workers] of [['originalStack',0],['poolStack',4]]){for(const [label,count,c] of parts){const n=label==='CPU workers'?workers:count;const part=document.createElement('span');part.style.width=`${n/1029*100}%`;part.style.background=color(c);part.title=`${label}: ${n}`;document.getElementById(id).append(part)}}
for(const [label,count,c] of parts){const item=document.createElement('span');const dot=document.createElement('i');dot.style.background=color(c);item.append(dot,document.createTextNode(label));document.getElementById('legend').append(item)}
</script></body></html>'''.replace('__DATA__',json.dumps(data))
Path('benchmarks/hybrid-ab-visual.html').write_text(html)
